@page "/settings"
@using sv_bed22849423a476588729a23452dcb7b.Models
@using sv_bed22849423a476588729a23452dcb7b.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h3>Settings</h3>
        <ul>
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    @section.Value
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <p>Loading...</p>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfile()
                    break;
                case "notifications":
                    @RenderNotifications()
                    break;
                case "security":
                    @RenderSecurity()
                    break;
                case "appearance":
                    @RenderAppearance()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastMessage
            </div>
        }
    </main>
</div>

@code {
    private readonly Dictionary<string, string> _sections = new()
    {
        ["profile"] = "Profile",
        ["notifications"] = "Notifications",
        ["security"] = "Security",
        ["appearance"] = "Appearance"
    };

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // Profile state
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private UserProfile? _savedProfile;

    // Notifications state
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = ["general", "announcements", "marketing", "engineering", "design"];
    private HashSet<string> _mutedChannels = [];

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private string? _sessionToRevoke;
    private bool _showRevokeConfirmation;

    // Appearance state
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private readonly string[] _themes = ["Light", "Dark", "System"];
    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        var profile = profileTask.Result;
        _savedProfile = profile;
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;

        var notif = notifTask.Result;
        _emailNotifications = notif.EmailNotifications;
        _pushNotifications = notif.PushNotifications;
        _weeklyDigest = notif.WeeklyDigest;
        _mutedChannels = [.. notif.MutedChannels];

        _securitySettings = securityTask.Result;
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        var appearance = appearanceTask.Result;
        _theme = appearance.Theme;
        _fontSize = appearance.FontSize;
        _language = appearance.Language;
        _compactMode = appearance.CompactMode;
    }

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    // --- Profile ---
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            _displayName = _savedProfile.DisplayName;
            _email = _savedProfile.Email;
            _avatarUrl = _savedProfile.AvatarUrl;
            _bio = _savedProfile.Bio;
        }
    }

    // --- Notifications ---
    private async Task SaveNotificationPrefs()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    // --- Security ---
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", true);
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!");
    }

    private void PromptRevokeSession(string sessionId)
    {
        _sessionToRevoke = sessionId;
        _showRevokeConfirmation = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            await ShowToast("Session revoked.");
        }
        _showRevokeConfirmation = false;
        _sessionToRevoke = null;
    }

    private void CancelRevokeSession()
    {
        _showRevokeConfirmation = false;
        _sessionToRevoke = null;
    }

    // --- Appearance ---
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    // --- Render fragments ---
    private RenderFragment RenderProfile() => __builder =>
    {
        <h2>Profile</h2>

        <div class="form-group avatar-section">
            <label>Avatar Preview</label>
            <div class="avatar-preview">
                <img src="@_avatarUrl" alt="Avatar" />
            </div>
            <span class="avatar-url">@_avatarUrl</span>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="_displayName" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="_email" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="_bio" rows="4"></textarea>
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    };

    private RenderFragment RenderNotifications() => __builder =>
    {
        <h2>Notifications</h2>

        <div class="form-group toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_emailNotifications" />
                <span class="toggle-switch"></span>
                Email Notifications
            </label>
        </div>

        <div class="form-group toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_pushNotifications" />
                <span class="toggle-switch"></span>
                Push Notifications
            </label>
        </div>

        <div class="form-group toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span class="toggle-switch"></span>
                Weekly Digest
            </label>
        </div>

        <h3>Muted Channels</h3>
        <div class="channel-list">
            @foreach (var channel in _allChannels)
            {
                var isMuted = _mutedChannels.Contains(channel);
                <label class="channel-item">
                    <input type="checkbox" checked="@isMuted"
                           @onchange="(e) => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                    @channel
                </label>
            }
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
        </div>
    };

    private RenderFragment RenderSecurity() => __builder =>
    {
        <h2>Security</h2>

        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                <span>Change Password</span>
                <span class="expand-icon">@(_changePasswordExpanded ? "▾" : "▸")</span>
            </button>

            @if (_changePasswordExpanded)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPwd">Current Password</label>
                        <input id="currentPwd" type="password" @bind="_currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPwd">New Password</label>
                        <input id="newPwd" type="password" @bind="_newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPwd">Confirm Password</label>
                        <input id="confirmPwd" type="password" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                </div>
            }
        </div>

        <div class="form-group toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_twoFactorEnabled" />
                <span class="toggle-switch"></span>
                Two-Factor Authentication
                <span class="status-indicator @(_twoFactorEnabled ? "status-enabled" : "status-disabled")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </label>
        </div>

        @if (_securitySettings?.LastPasswordChange is not null)
        {
            <p class="info-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }

        <h3>Active Sessions</h3>
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @if (_securitySettings?.Sessions is not null)
                {
                    @foreach (var session in _securitySettings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != _securitySettings.Sessions.First().Id)
                                {
                                    <button class="btn btn-danger btn-sm" @onclick="() => PromptRevokeSession(session.Id)">Revoke</button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                }
            </tbody>
        </table>

        @if (_showRevokeConfirmation)
        {
            <div class="modal-overlay">
                <div class="modal-dialog">
                    <h4>Confirm Revocation</h4>
                    <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
                    <div class="button-group">
                        <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Revoke Session</button>
                        <button class="btn btn-secondary" @onclick="CancelRevokeSession">Cancel</button>
                    </div>
                </div>
            </div>
        }
    };

    private RenderFragment RenderAppearance() => __builder =>
    {
        <h2>Appearance</h2>

        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                @foreach (var theme in _themes)
                {
                    <label class="radio-label">
                        <input type="radio" name="theme" value="@theme" checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        @theme
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                @foreach (var size in _fontSizes)
                {
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="@size" checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        @size
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="form-group toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_compactMode" />
                <span class="toggle-switch"></span>
                Compact Mode
            </label>
        </div>

        <div class="preview-area @GetPreviewClasses()">
            <h4>Live Preview</h4>
            <p>This is how your content will look with the selected settings.</p>
            <p><strong>Theme:</strong> @_theme | <strong>Font:</strong> @_fontSize | <strong>Language:</strong> @_language</p>
            <p>@(_compactMode ? "Compact spacing applied." : "Standard spacing applied.")</p>
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_fontSize.ToLowerInvariant()}");
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }
}

